"""Static file templates used by the scaffolder.

Each value is a :class:`string.Template` so substitution uses ``$var`` and
no JSON/JSX brace needs escaping. Specialists fill in entity-specific code
on top of this skeleton; nothing here is meant to be edited by the LLM
unless absolutely necessary.
"""

from __future__ import annotations

from string import Template

# =============================================================== root level

