_BACKEND_START_SH = Template(
    """#!/bin/sh
# Boot script for the backend container.
#
# Strategy:
#   1. Try `alembic upgrade head` (preferred when the specialist generated
#      an initial migration).
#   2. If that fails OR no migrations exist, fall back to
#      `Base.metadata.create_all(engine)` so the app still has tables and
#      the stack can come up. This makes the generated docker-compose
#      smoke-startable even when the migration step is incomplete.
#   3. Hand off to uvicorn.
set -e

echo "[start.sh] running migrations..."
if ! alembic upgrade head; then
  echo "[start.sh] alembic upgrade failed; falling back to metadata.create_all" >&2
fi

python - <<'PY'
try:
    from app.db import Base, engine
    from app import models  # noqa: F401  populate metadata
    Base.metadata.create_all(engine)
    print("[start.sh] ensured tables via Base.metadata.create_all")
except Exception as exc:  # noqa: BLE001
    print(f"[start.sh] metadata.create_all skipped: {exc}")
PY

echo "[start.sh] starting uvicorn on 0.0.0.0:$backend_port"
exec uvicorn app.main:app --host 0.0.0.0 --port $backend_port
"""
)

