_FRONTEND_APP_TSX = Template(
    """import { Link, Route, Routes, Navigate } from "react-router-dom";
import LoginPage from "./pages/LoginPage";
import RegisterPage from "./pages/RegisterPage";
import HomePage from "./pages/HomePage";
import { useAuth } from "./lib/auth";

function Protected({ children }: { children: JSX.Element }) {
  const { token } = useAuth();
  return token ? children : <Navigate to="/login" replace />;
}

export default function App() {
  const { token, logout } = useAuth();
  return (
    <div className="min-h-screen bg-gray-50 text-gray-900">
      <header className="bg-white border-b">
        <nav className="max-w-5xl mx-auto px-4 py-3 flex gap-4 items-center">
          <Link to="/" className="font-semibold">$project_title</Link>
          <div className="ml-auto flex gap-3">
            {token ? (
              <button onClick={logout} className="text-sm text-gray-600 hover:text-gray-900">
                Log out
              </button>
            ) : (
              <>
                <Link to="/login" className="text-sm">Log in</Link>
                <Link to="/register" className="text-sm">Register</Link>
              </>
            )}
          </div>
        </nav>
      </header>
      <main className="max-w-5xl mx-auto p-4">
        <Routes>
          <Route path="/" element={<Protected><HomePage /></Protected>} />
          <Route path="/login" element={<LoginPage />} />
          <Route path="/register" element={<RegisterPage />} />
          {/* >>> AUTOGEN ROUTES <<< */}
        </Routes>
      </main>
    </div>
  );
}
"""
)

_FRONTEND_LIB_API = Template(
    """import axios from "axios";
import { getToken } from "./auth";

export const api = axios.create({
  baseURL: import.meta.env.VITE_API_URL ?? "http://localhost:$backend_port",
});

api.interceptors.request.use((config) => {
  const token = getToken();
  if (token) {
    config.headers.Authorization = `Bearer $${token}`;
  }
  return config;
});
"""
)

_FRONTEND_LIB_AUTH = Template(
    """import { useEffect, useState } from "react";

const STORAGE_KEY = "auth_token";

export function getToken(): string | null {
  return typeof window === "undefined" ? null : window.localStorage.getItem(STORAGE_KEY);
}

export function setToken(token: string | null) {
  if (typeof window === "undefined") return;
  if (token) window.localStorage.setItem(STORAGE_KEY, token);
  else window.localStorage.removeItem(STORAGE_KEY);
  window.dispatchEvent(new Event("auth-change"));
}

export function useAuth() {
  const [token, setLocalToken] = useState<string | null>(getToken());

  useEffect(() => {
    const onChange = () => setLocalToken(getToken());
    window.addEventListener("auth-change", onChange);
    return () => window.removeEventListener("auth-change", onChange);
  }, []);

  return {
    token,
    logout: () => setToken(null),
  };
}
"""
)

_FRONTEND_LOGIN_PAGE = Template(
    """import { FormEvent, useState } from "react";
import { useNavigate } from "react-router-dom";
import { api } from "../lib/api";
import { setToken } from "../lib/auth";

export default function LoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setError(null);
    try {
      const form = new URLSearchParams();
      form.append("username", email);
      form.append("password", password);
      const res = await api.post("/auth/login", form, {
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
      });
      setToken(res.data.access_token);
      navigate("/");
    } catch {
      setError("Invalid credentials");
    }
  }

  return (
    <form onSubmit={onSubmit} className="max-w-sm mx-auto bg-white p-6 rounded shadow space-y-3">
      <h1 className="text-xl font-semibold">Log in</h1>
      <input className="w-full border rounded px-3 py-2" type="email" placeholder="Email"
        value={email} onChange={(e) => setEmail(e.target.value)} required />
      <input className="w-full border rounded px-3 py-2" type="password" placeholder="Password"
        value={password} onChange={(e) => setPassword(e.target.value)} required />
      {error && <p className="text-red-600 text-sm">{error}</p>}
      <button className="w-full bg-blue-600 text-white py-2 rounded">Log in</button>
    </form>
  );
}
"""
)

_FRONTEND_REGISTER_PAGE = Template(
    """import { FormEvent, useState } from "react";
import { useNavigate } from "react-router-dom";
import { api } from "../lib/api";

export default function RegisterPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setError(null);
    try {
      await api.post("/auth/register", { email, password });
      navigate("/login");
    } catch {
      setError("Registration failed");
    }
  }

  return (
    <form onSubmit={onSubmit} className="max-w-sm mx-auto bg-white p-6 rounded shadow space-y-3">
      <h1 className="text-xl font-semibold">Register</h1>
      <input className="w-full border rounded px-3 py-2" type="email" placeholder="Email"
        value={email} onChange={(e) => setEmail(e.target.value)} required />
      <input className="w-full border rounded px-3 py-2" type="password" placeholder="Password"
        value={password} onChange={(e) => setPassword(e.target.value)} required />
      {error && <p className="text-red-600 text-sm">{error}</p>}
      <button className="w-full bg-blue-600 text-white py-2 rounded">Create account</button>
    </form>
  );
}
"""
)

